SET data = '{"scope":"expanded","status":"source_reviewed","aliases":["Lioresal"],"diseases":["espasticidade","espasticidade medular ou cerebral","espasticidade na esclerose múltipla"],"products":[{"name":"Baclon","type":"marca/apresentação","source_url":"https://uploads.consultaremedios.com.br/drug_leaflet/pro/Bula-Baclon-Profissional-Consulta-Remedios.pdf","presentation":"Comprimido sulcado 10 mg, caixa 20."},{"name":"Lioresal","type":"marca/apresentação","source_url":"https://portal.novartis.com.br/medicamentos/wp-content/uploads/2021/10/Bula-LIORESAL-Comprimido-Paciente.pdf","presentation":"Comprimidos 10 mg"}],"indications":["espasticidade","espasticidade medular ou cerebral","espasticidade na esclerose múltipla"],"leaflet_url":"https://uploads.consultaremedios.com.br/drug_leaflet/pro/Bula-Baclon-Profissional-Consulta-Remedios.pdf","reviewed_at":"2026-11-02","source_urls":["https://portal.novartis.com.br/medicamentos/wp-content/uploads/2021/10/Bula-LIORESAL-Comprimido-Paciente.pdf","https://uploads.consultaremedios.com.br/drug_leaflet/pro/Bula-Baclon-Profissional-Consulta-Remedios.pdf"],"formulations":[{"label":"Comprimidos 10 mg","route":"VO","cautions":"Sedação, tontura e fraqueza são frequentes. Ajustar em insuficiência renal, evitar álcool e outros depressores do SNC e não interromper abruptamente devido a risco de abstinência, alucinações e convulsões.","dose_text":"Iniciar 5 mg VO 3 vezes ao dia por 3 dias; depois 10 mg 3 vezes/dia por 3 dias; 15 mg 3 vezes/dia por 3 dias; 20 mg 3 vezes/dia por 3 dias. Após isso, titular pela resposta com a menor dose eficaz.","population":"Adultos; segurança/eficácia pediátrica da formulação oral deve seguir bula específica.","safe_limit":"Máximo oral padrão: 80 mg/dia.","source_url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c17527be-661d-42f5-b6f6-56a681ba7870","duration_text":"Tratamento contínuo enquanto houver benefício. Se for suspender após uso contínuo, reduzir gradualmente para evitar abstinência.","interval_text":"8/8 horas (iniciar 5 mg de 8/8h e titular progressivamente a cada 3 dias)","administration":"Via oral, com ou sem alimentos. Em insuficiência renal, reduzir exposição e titular com extrema cautela; não interromper abruptamente.","max_daily_text":"80 mg/dia no esquema oral padrão (20 mg 4 vezes/dia).","posology_lines":["Dias 1–3: 5 mg VO 3x/dia.","Dias 4–6: 10 mg VO 3x/dia.","Dias 7–9: 15 mg VO 3x/dia.","Dias 10–12: 20 mg VO 3x/dia.","Depois: titular pela resposta; máximo 80 mg/dia."],"prescription_type":"Sob prescrição."},{"label":"Baclon comprimido sulcado 10 mg, caixa 20","route":"Oral","cautions":"Insuficiência renal pode causar toxicidade mesmo em dose baixa; monitorar sedação, quedas e interações depressoras do SNC. Não suspender abruptamente.","dose_text":"Iniciar 15 mg/dia em 2–4 tomadas (ex.: 5 mg 3 vezes/dia); aumentar cautelosamente ~15 mg/dia a cada 3 dias conforme tolerância. Usual 30–80 mg/dia.","population":"Adultos","source_url":"https://uploads.consultaremedios.com.br/drug_leaflet/pro/Bula-Baclon-Profissional-Consulta-Remedios.pdf","duration_text":"Contínuo conforme resposta; retirada gradual por 1–2 semanas.","interval_text":"8/8 horas (iniciar 5 mg de 8/8h e titular progressivamente a cada 3 dias)","administration":"Tomar durante refeições com líquido; comprimido é sulcado.","max_daily_text":"80 mg/dia é limite usual de otimização; doses de 100–120 mg/dia somente em pacientes hospitalizados com monitoramento conforme bula.","posology_lines":["Iniciar 15 mg/dia em 2–4 tomadas (ex.: 5 mg 3 vezes/dia)","aumentar cautelosamente ~15 mg/dia a cada 3 dias conforme tolerância.","Usual 30–80 mg/dia."],"prescription_type":"Sob prescrição."}],"presentation":"Comprimido sulcado 10 mg, caixa 20.\n• Comprimidos 10 mg","quality_audit":{"batch":"bul-06-251-300","scope":"presentation_source_safety_fields_and_targeted_medical_review","priority":"P1","screened_at":"2026-10-15","clinical_area":"Neurologia","review_status":"PENDING_CLINICAL_SOURCE_REVIEW","action_required":"Baclofeno: duas apresentações orais 10 mg; conferir retirada gradual, função renal e cautelas de sedação.","formulation_count":2,"scientifically_validated":false,"generic_placeholder_forms":0,"prescription_copy_blocked":false,"missing_core_safety_fields":[],"missing_source_formulations":0,"repeated_formulation_label_groups":0},"deduplicated_at":"2026-09-29","commercial_names":["Baclon","Lioresal"],"renal_adjustment":"Reduzir dose e titular lentamente em insuficiência renal; em doença renal grave ou diálise, risco de neurotoxicidade importante exige esquema especializado.","adverse_reactions":["Fraqueza muscular","Náusea (muito comum)","Sonolência","Sonolência/sedação (muito comum)","Tontura","Tontura, ataxia ou fraqueza muscular"],"contraindications":["Hipersensibilidade ao baclofeno ou a qualquer componente da formulação."],"drug_interactions":["Álcool, opioides e outros depressores do SNC aumentam sedação","Álcool, opioides e outros depressores do SNC: sedação e risco respiratório maiores","Anti-hipertensivos podem intensificar hipotensão","Anti-hipertensivos: maior queda da pressão arterial","Fármacos que reduzem função renal podem aumentar toxicidade do baclofeno","Levodopa/carbidopa: relatos de confusão/alucinações; lítio e tricíclicos exigem cautela"],"safety_source_url":"https://uploads.consultaremedios.com.br/drug_leaflet/pro/Bula-Baclon-Profissional-Consulta-Remedios.pdf","safety_updated_at":"2026-09-28","hepatic_adjustment":"Não há ajuste hepático específico usual; usar com cautela em hepatopatia grave devido à maior sensibilidade a sedação.","safety_reviewed_at":"2026-09-29","overdose_management":"Superdose pode causar coma, depressão respiratória, hipotonia e convulsões. Suporte de via aérea e ventilação é prioritário; hemodiálise pode ser útil especialmente em insuficiência renal grave.","safety_review_status":"source_reviewed","indications_backfilled_at":"2026-10-02","clinical_status":"verified_strict_hours"}'::jsonb
