SET data = '{"scope":"expanded","status":"source_reviewed","diseases":["reações alérgicas (tratamento sintomático)","prevenção de náusea de viagem e vômitos pós-operatórios","pré-anestesia e sedação adjuvante"],"products":[{"name":"Fenergan","type":"marca","presentation":"comprimido revestido 25 mg (20)"},{"name":"cloridrato de prometazina","type":"genérico","presentation":"conferir concentração e bula do fabricante"}],"synonyms":["cloridrato de prometazina"],"indications":["reações alérgicas (tratamento sintomático)","prevenção de náusea de viagem e vômitos pós-operatórios","pré-anestesia e sedação adjuvante"],"leaflet_url":"https://uploads.consultaremedios.com.br/drug_leaflet/pro/Bula-Fenergan-Comprimido-Profissional-Consulta-Remedios.pdf","reviewed_at":"2026-11-02","source_urls":["https://uploads.consultaremedios.com.br/drug_leaflet/pro/Bula-Fenergan-Comprimido-Profissional-Consulta-Remedios.pdf"],"formulations":[{"label":"Fenergan comprimido revestido 25 mg — 20","route":"Oral","cautions":"Uso adulto nesta apresentação. Não é tratamento único da anafilaxia. Contraindicado em coma/depressão do SNC, glaucoma de ângulo fechado e risco de retenção urinária; evitar álcool e avaliar QT, sedação e fragilidade em idosos. Bula não discrimina doses diferentes por indicação.","dose_text":"2 a 6 comprimidos por dia (50–150 mg/dia), em doses divididas conforme bula.","population":"Adultos","safe_limit":"150 mg/dia nesta apresentação oral segundo a ficha cadastrada.","source_url":"https://uploads.consultaremedios.com.br/drug_leaflet/pro/Bula-Fenergan-Comprimido-Profissional-Consulta-Remedios.pdf","duration_text":"Conforme indicação e resposta; evitar uso prolongado sem reavaliação.","interval_text":"Dividir em 2, 3 ou 4 tomadas; maior fração à noite. (administrado em intervalos regulares de 8/8h ou 12/12h conforme prescrição)","administration":"VO com líquido; não partir ou mastigar.","max_daily_text":"150 mg/dia nesta apresentação, conforme posologia da bula.","posology_lines":["Alergia/antiemese/pré-anestesia, adulto: a bula orienta 50–150 mg/dia VO, divididos em 2–4 tomadas, com maior fração à noite; individualizar conforme objetivo e sedação.","Esta bula do comprimido não fornece esquema separado para cada indicação; confirmar protocolo específico para pré-anestesia e anafilaxia."],"prescription_type":"Venda sob prescrição médica."}],"presentation":"Comprimido revestido 25 mg de prometazina base (equivalente a 28,20 mg de cloridrato), 20 unidades.","quality_audit":{"batch":"bul-10-451-500","scope":"individual_formulation_source_safety_risk_and_duplicate_name_triage","priority":"P1","screened_at":"2026-10-15","clinical_area":"Clínica/Alergia","review_status":"PENDING_CLINICAL_SOURCE_REVIEW","action_required":"Prometazina comprimido 25 mg: revisar sedação, risco anticolinérgico, interações e contraindicação/limites etários pediátricos.","formulation_count":1,"source_review_status":"SOURCE_URL_PRESENT_DOES_NOT_IMPLY_CLINICAL_VALIDATION","scientifically_validated":false,"generic_placeholder_forms":0,"prescription_copy_blocked":false,"missing_core_safety_fields":[],"missing_source_formulations":0,"repeated_formulation_label_groups":0,"retailer_or_aggregator_hosted_formulations":1},"commercial_names":["Fenergan"],"renal_adjustment":"Não há ajuste renal específico geralmente necessário.","adverse_reactions":["Sedação e sonolência muito comuns; tontura, boca seca, constipação e retenção urinária","Efeitos extrapiramidais, confusão e hipotensão","Prolongamento QT/torsades, depressão respiratória e discrasias sanguíneas relatados"],"contraindications":["Hipersensibilidade à prometazina, a outros derivados fenotiazínicos ou a qualquer componente da formulação.","Discrasias sanguíneas ou antecedente de agranulocitose com outros fenotiazínicos.","Risco de retenção urinária relacionado a distúrbios uretroprostáticos.","Glaucoma de ângulo fechado.","Coma ou depressão do sistema nervoso central por qualquer causa.","Uso concomitante de álcool ou sultoprida.","Aleitamento.","Menores de 2 anos."],"drug_interactions":["Álcool, opioides, sedativos e hipnóticos: depressão do SNC aumentada.","IMAO: evitar durante uso e nos 14 dias anteriores.","Anticolinérgicos e tricíclicos: efeitos anticolinérgicos aumentados.","Fármacos que prolongam QT: maior risco de arritmia.","Antiácidos contendo magnésio/alumínio/cálcio: separar pelo menos 2 h se possível."],"safety_source_url":"https://uploads.consultaremedios.com.br/drug_leaflet/pro/Bula-Fenergan-Comprimido-Profissional-Consulta-Remedios.pdf","hepatic_adjustment":"Usar com cautela em hepatopatia.","safety_reviewed_at":"2026-09-28","overdose_management":"Superdose pode causar depressão do SNC, hipotensão e efeitos anticolinérgicos. Tratamento de suporte.","safety_review_status":"source_reviewed","indications_backfilled_at":"2026-10-02","source_urls_backfilled_at":"2026-10-02","clinical_status":"verified_strict_hours"}'::jsonb
