ministration":"Tomar com ½–1 copo de líquido; não partir nem mastigar o comprimido de 500 mg.","max_daily_text":"8 comprimidos de 500 mg = 4.000 mg/24 h.","posology_lines":["1–2 comprimidos (500–1.000 mg) por tomada.","Intervalo: Até 4 tomadas ao dia, conforme necessidade.","Via: Via oral","Duração: Conforme sintomas e reavaliação clínica.","Máximo: 8 comprimidos de 500 mg = 4.000 mg/24 h.","Administração: Tomar com ½–1 copo de líquido; não partir nem mastigar o comprimido de 500 mg."],"prescription_type":"Conferir exigência de receita da apresentação."},{"label":"Dipirona gotas 500 mg/mL","route":"VO","cautions":"Risco raro de agranulocitose e reações de hipersensibilidade; evitar duplicidade com outras apresentações de dipirona.","dose_text":"Pediatria 5–8 kg: 2–5 gotas/dose; 9–15 kg: 3–10; 16–23 kg: 5–15; 24–30 kg: 8–20; 31–45 kg: 10–30; 46–53 kg: 15–35 gotas/dose.","safe_limit":"Não exceder o limite por peso/faixa etária.","duration_text":"Uso sintomático curto; reavaliar se febre/dor persistirem.","interval_text":"A cada 6 h se necessário, até 4 tomadas/dia.","administration":"Usar a concentração 500 mg/mL e o gotejador da própria apresentação.","max_daily_text":"Máximo diário por peso: 20, 40, 60, 80, 120 ou 140 gotas, respectivamente.","posology_lines":["Pediatria 5–8 kg: 2–5 gotas/dose; 9–15 kg: 3–10; 16–23 kg: 5–15; 24–30 kg: 8–20; 31–45 kg: 10–30; 46–53 kg: 15–35 gotas/dose.","Intervalo: A cada 6 h se necessário, até 4 tomadas/dia.","Máximo: Máximo diário por peso: 20, 40, 60, 80, 120 ou 140 gotas, respectivamente."],"reference_weight":"Peso corporal atual.","prescription_type":"Conforme apresentação vigente.","pediatric_dose_text":"Usar tabela por peso da bula da solução 500 mg/mL."},{"label":"Dipirona solução oral infantil 50 mg/mL","route":"VO","cautions":"Não confundir com solução 500 mg/mL; diferenças de concentração podem causar erro grave.","dose_text":"Solução oral 50 mg/mL: 5–8 kg: 1,25–2,5 mL/dose; 9–15 kg: 2,5–5 mL; 16–23 kg: 3,75–7,5 mL; 24–30 kg: 5–10 mL; 31–45 kg: 7,5–15 mL; 46–53 kg: 8,75–17,5 mL.","safe_limit":"Não converter gotas/mL entre concentrações diferentes.","duration_text":"Uso sintomático curto.","interval_text":"A cada 6 h se necessário, até 4 tomadas/dia.","administration":"Medir com dispositivo graduado.","max_daily_text":"Máximo diário por peso: 10, 20, 30, 40, 60 ou 70 mL, respectivamente.","posology_lines":["Solução oral 50 mg/mL: 5–8 kg: 1,25–2,5 mL/dose; 9–15 kg: 2,5–5 mL; 16–23 kg: 3,75–7,5 mL; 24–30 kg: 5–10 mL; 31–45 kg: 7,5–15 mL; 46–53 kg: 8,75–17,5 mL.","Intervalo: A cada 6 h se necessário, até 4 tomadas/dia.","Máximo: Máximo diário por peso: 10, 20, 30, 40, 60 ou 70 mL, respectivamente."],"reference_weight":"Peso corporal atual.","prescription_type":"Conforme apresentação vigente.","pediatric_dose_text":"Apresentação infantil 50 mg/mL; calcular pela tabela de peso."}],"presentation":"Comprimidos; conferir concentração e formulação.","quality_audit":{"batch":"bul-01-050","scope":"structural_presence_source_and_safety_field_review","priority":"P0","screened_at":"2026-10-15","clinical_area":"Analgesia","review_status":"PENDING_CLINICAL_SOURCE_REVIEW","action_required":"Dipirona: gotas 500 mg/mL e solução infantil 50 mg/mL sem link próprio de bula; revisar risco de confusão 10x e mg por gota.","scientifically_validated":false,"missing_core_safety_fields":[],"missing_source_formulations":2},"commercial_names":["Novalgina","Novalgina Comprimido"],"renal_adjustment":"Em insuficiência renal grave, evitar doses altas/repetidas e monitorar.","adverse_reactions":["Reações anafiláticas ou anafilactoides, inclusive choque","Agranulocitose potencialmente grave, que pode ocorrer independentemente da dose","Hipotensão","Reações cutâneas graves, incluindo síndrome de Stevens-Johnson e necrólise epidérmica tóxica","Lesão renal aguda, especialmente em pacientes suscetíveis"],"contraindications":["Hipersensibilidade à dipirona, a qualquer componente da formulação ou a outras pirazolonas/pirazolidinas.","História de agranulocitose causada por dipirona ou fármacos da classe pirazolona/pirazolidina.","Função da medula óssea prejudicada ou doenças do sistema hematopoiético.","História de broncoespasmo ou outras reações anafilactoides após uso de analgésicos como salicilatos, paracetamol, diclofenaco, ibuprofeno, indometacina ou naproxeno.","Porfiria hepática aguda intermitente.","Deficiência congênita de glicose-6-fosfato-desidrogenase (G6PD).","Uso durante a amamentação; para gestação, seguir as restrições específicas da bula e avaliação médica."],"drug_interactions":["Valproato: pode diminuir níveis séricos; monitorar resposta clínica e considerar dosagem.","Metotrexato: pode aumentar hematotoxicidade, sobretudo em idosos; evitar associação.","Ácido acetilsalicílico em baixa dose: pode reduzir efeito antiplaquetário; usar com cautela.","Substratos de CYP2B6/CYP3A4, como bupropiona, ciclosporina e tacrolimo: concentrações podem cair; monitorar."],"safety_source_url":"https://www.novalgina.com.br/produtos/adulto/1g-comprimido/bula","hepatic_adjustment":"Em insuficiência hepática, evitar doses altas/repetidas e monitorar.","safety_reviewed_at":"2026-09-29","overdose_management":"Superdose pode causar náuseas, hipotensão, insuficiência renal e convulsões. Tratamento de suporte.","posology_cleanup_at":"2026-10-02","safety_review_status":"source_reviewed","posology_cleanup_batch":"posology_cleanup_13","indications_backfilled_at":"2026-10-02","source_urls_backfilled_at":"2026-10-02","clinical_status":"verified_strict_hours"}'::jsonb
