UPDATE public.bulario_drugs 
SET data = '{"scope":"expanded","status":"source_reviewed","diseases":["diabetes mellitus tipo 2","pré-diabetes com fatores de risco específicos","síndrome dos ovários policísticos"],"products":[{"name":"Glifage","type":"marca","presentation":"liberação imediata 500 mg, 850 mg e 1 g"},{"name":"Glifage XR","type":"marca","presentation":"liberação prolongada 500 mg, 750 mg, 850 mg e 1 g"},{"name":"cloridrato de metformina","type":"genérico","presentation":"conferir fabricante e forma de liberação"}],"synonyms":["metformina"],"indication":"Tratamento do diabetes tipo 2; prevenção em pré-diabetes de alto risco e síndrome dos ovários policísticos nas condições descritas na bula.","indications":["diabetes mellitus tipo 2","pré-diabetes com fatores de risco específicos","síndrome dos ovários policísticos"],"leaflet_url":"https://consultaremedios.com.br/glifage/bula","reviewed_at":"2026-11-02","source_urls":["https://uploads.consultaremedios.com.br/drug_leaflet/pro/Bula-Glifage-Profissional-Consulta-Remedios.pdf"],"formulations":[{"label":"Glifage comprimido revestido 500 mg (liberação imediata)","route":"Via oral","cautions":"Avaliar TFGe antes e durante uso; com TFGe 30–59, máximo 1.000 mg/dia se elegível, e suspender se <30. Considerar cirurgia/contraste iodado e risco de acidose láctica.","dose_text":"Adultos: iniciar 500 mg 2 vezes/dia; aumentar 500 mg/dia a cada semana se necessário. >10 anos: iniciar 500 mg 1 vez/dia, titular conforme resposta.","population":"Adultos com DM2; crianças acima de 10 anos com DM2","safe_limit":"Adultos: 2.500 mg/24 h (5 comprimidos). Pediatria: 2.000 mg/24 h (4 comprimidos). TFGe 30–59: 1.000 mg/dia se elegível.","source_url":"https://uploads.consultaremedios.com.br/drug_leaflet/pro/Bula-Glifage-Profissional-Consulta-Remedios.pdf","duration_text":"Uso contínuo, com revisão da resposta e função renal.","interval_text":"Adultos: com café e jantar, podendo dividir em 3 tomadas. Pediatria: diário, dividido conforme titulação. (administrado e