SET data = '{"scope":"expanded","status":"source_reviewed","diseases":["Candidíase oral","Candidíase do trato digestivo superior","Candidíase vaginal"],"products":[{"name":"Nistatina Cristália","type":"genérico","presentation":"Suspensão oral 100.000 UI/mL; frasco 50 mL com conta-gotas"},{"name":"Nistatina Geolab","type":"genérico","presentation":"Creme vaginal 25.000 UI/g; bisnaga 60 g com 14 aplicadores"}],"indications":["Candidíase oral","Candidíase do trato digestivo superior","Candidíase vaginal"],"leaflet_url":"https://www.cristalia.com.br/produto/266/bula-profissional","reviewed_at":"2026-11-02","source_urls":["https://www.cristalia.com.br/produto/266/bula-profissional","https://www.geolab.com.br/wp-content/uploads/2021/05/NISTATINA-Bula-Profissional.pdf"],"formulations":[{"label":"Suspensão oral 100.000 UI/mL — candidíase oral e do trato digestivo superior","route":"oral","cautions":"Não tratar micose sistêmica. Contém sacarose e etanol; cautela em diabetes e crianças.","dose_text":"1 mL (100.000 UI) por dose","population":"Prematuros e crianças de baixo peso","source_url":"https://www.cristalia.com.br/produto/266/bula-profissional","duration_text":"Manter pelo menos 48 h após desaparecimento dos sintomas e negativação das culturas; reavaliar se persistir após 14 dias.","interval_text":"6/6 horas","administration":"Agitar; distribuir metade da dose em cada lado da boca, mantendo contato com a mucosa antes de engolir.","max_daily_text":"Bula não estabelece teto específico; esquema descrito: 4 mL/dia (400.000 UI).","posology_lines":["Prematuros/baixo peso: 1 mL VO 4 vezes ao dia.","Manter ≥48 h após resolução clínica e negativação das culturas."],"prescription_type":"prescrição médica"},{"label":"Suspensão oral 100.000 UI/mL — candidíase oral e do trato digestivo superior","route":"oral","cautions":"Não tratar micose sistêmica. Contém sacarose e etanol.","dose_text":"1–2 mL (100.000–200.000 UI) por dose","population":"Lactentes","source_url":"https://www.cristalia.com.br/produto/266/bula-profissional","duration_text":"Manter pelo menos 48 h após desaparecimento dos sintomas e negativação das culturas; reavaliar se persistir após 14 dias.","interval_text":"6/6 horas","administration":"Agitar; colocar metade da dose em cada lado da boca antes de engolir.","max_daily_text":"Bula não estabelece teto específico; faixa descrita: até 8 mL/dia (800.000 UI).","posology_lines":["Lactentes: 1–2 mL VO 4 vezes ao dia.","Manter ≥48 h após resolução clínica e negativação das culturas."],"prescription_type":"prescrição médica"},{"label":"Suspensão oral 100.000 UI/mL — candidíase oral e do trato digestivo superior","route":"oral","cautions":"Não tratar micose sistêmica. Contém sacarose (500 mg/mL) e etanol; cautela em diabetes.","dose_text":"1–6 mL (100.000–600.000 UI) por dose","population":"Crianças e adultos","source_url":"https://www.cristalia.com.br/produto/266/bula-profissional","duration_text":"Manter pelo menos 48 h após desaparecimento dos sintomas e negativação das culturas; reavaliar se persistir após 14 dias.","interval_text":"6/6 horas","administration":"Agitar; bochechar e manter na cavidade oral por vários minutos antes de engolir; higienizar boca e próteses.","max_daily_text":"Bula não estabelece teto específico; faixa descrita: até 24 mL/dia (2.400.000 UI).","posology_lines":["Crianças/adultos: 1–6 mL VO 4 vezes ao dia.","Bochechar, manter contato com a mucosa e engolir.","Manter ≥48 h após resolução clínica e negativação das culturas."],"prescription_type":"prescrição médica"},{"label":"Creme vaginal 25.000 UI/g — candidíase vaginal","route":"intravaginal","cautions":"Uso ginecológico exclusivo. Petrolato reduz eficácia de preservativos/diafragmas de látex. Gestação: evitar pressão do aplicador contra o colo uterino.","dose_text":"1 aplicador cheio por aplicação; em casos graves, até 2 aplicadores cheios conforme avaliação","population":"Adultas","source_url":"https://www.geolab.com.br/wp-content/uploads/2021/05/NISTATINA-Bula-Profissional.pdf","duration_text":"14 dias consecutivos no esquema usual; não interromper durante a menstruação.","interval_text":"24/24 horas (dose única diária)","administration":"Preencher o aplicador e introduzir suavemente na vagina; descartar após uso.","max_daily_text":"Esquema da bula: até 2 aplicadores cheios ao dia em casos graves; massa por aplicador não especificada.","posology_lines":["Adultas: 1 aplicador cheio intravaginal 1 vez ao dia por 14 dias.","Casos graves: até 2 aplicadores cheios ao dia, conforme avaliação."],"prescription_type":"prescrição médica"}],"presentation":"Suspensão oral 100.000 UI/mL (50 mL); creme vaginal 25.000 UI/g (60 g, 14 aplicadores). As vias e esquemas não são intercambiáveis.","quality_audit":{"batch":"bul-06-251-300","scope":"presentation_source_safety_fields_and_targeted_medical_review","priority":"P1","screened_at":"2026-10-15","clinical_area":"Infectologia/Pediatria","review_status":"PENDING_CLINICAL_SOURCE_REVIEW","action_required":"Nistatina tem rótulos repetidos na suspensão oral; separar indicações, modo de uso e outras apresentações tópicas/vaginais.","formulation_count":4,"scientifically_validated":false,"generic_placeholder_forms":0,"prescription_copy_blocked":false,"missing_core_safety_fields":[],"missing_source_formulations":0,"repeated_formulation_label_groups":1},"commercial_names":["Nistatina Cristália","Nistatina Geolab"],"renal_adjustment":"Não há ajuste renal específico por baixa absorção sistêmica.","adverse_reactions":["Oral: diarreia, náuseas, vômitos ou desconforto gastrintestinal em doses elevadas; erupção cutânea/urticária raras.","Vaginal: irritação, ardor, prurido ou hipersensibilidade local."],"contraindications":["Hipersensibilidade à nistatina ou a qualquer componente da formulação."],"drug_interactions":["Suspensão oral: não são conhecidas interações medicamentosas na bula consultada.","Creme vaginal: interações medicamentosas desconhecidas; petrolato pode reduzir a eficácia de preser