terval_text":"8/8 horas ou 12/12 horas","administration":"1 hora antes das refeições.","max_daily_text":"Maioria responde com ≤150 mg/dia; teto absoluto de bula 450 mg/dia","posology_lines":["ICC: geralmente 25 mg VO 2–3 vezes ao dia.","Hipotensão/hipovolemia: considerar 6,25–12,5 mg 2–3 vezes ao dia sob supervisão.","Titular lentamente; usualmente ≤150 mg/dia."],"prescription_type":"prescrição médica"},{"label":"Comprimidos 25/50 mg — pós-infarto estável","route":"oral","cautions":"Não extrapolar a pacientes instáveis; monitorar hipotensão, potássio e função renal. Confirmar frações do comprimido.","dose_text":"6,25 mg inicial; então 37,5 mg/dia divididos em 3 tomadas; subir a 75 mg/dia e alvo 150 mg/dia","population":"Adultos estáveis, a partir do 3º dia","source_url":"https://geolab.com.br/wp-content/uploads/2021/05/CAPTOPRIL-Bula-Profissional.pdf","duration_text":"Titulação em dias e semanas conforme tolerância; manutenção individualizada.","interval_text":"8/8 horas","administration":"1 hora antes das refeições.","max_daily_text":"Alvo 150 mg/dia para esta indicação","posology_lines":["Após 3º dia e estabilidade: dose inicial 6,25 mg VO.","Depois 12,5 mg VO 3 vezes ao dia; subir a 25 mg 3 vezes ao dia.","Alvo final: 50 mg VO 3 vezes ao dia, conforme tolerância."],"prescription_type":"prescrição médica"},{"label":"Comprimidos 25/50 mg — nefropatia diabética","route":"oral","cautions":"Monitorar creatinina e potássio; insuficiência renal significativa requer início menor e titulação lenta.","dose_text":"75–100 mg/dia em doses divididas","population":"Adultos com diabetes insulinodependente e proteinúria >500 mg/dia","source_url":"https://geolab.com.br/wp-content/uploads/2021/05/CAPTOPRIL-Bula-Profissional.pdf","duration_text":"Tratamento contínuo.","interval_text":"Doses divididas (administrado em intervalos regulares de 8/8h ou 12/12h conforme prescrição)","administration":"1 hora antes das refeições.","max_daily_text":"100 mg/dia na faixa recomendada para esta indicação; ajuste renal individual","posology_lines":["Nefropatia diabética: 75–100 mg/dia VO em doses divididas."],"prescription_type":"prescrição médica"}],"presentation":"Comprimidos 25 mg e 50 mg (Geolab); conferir dose divisível na apresentação específica.","quality_audit":{"batch":"bul-01-050","scope":"structural_presence_source_and_safety_field_review","priority":"P1","screened_at":"2026-10-15","clinical_area":"Cardiorrenal","review_status":"PENDING_CLINICAL_SOURCE_REVIEW","action_required":"Captopril: repetição por quatro indicações; conferir intervalos e risco de rotular como uso sublingual.","scientifically_validated":false,"missing_core_safety_fields":[],"missing_source_formulations":0},"commercial_names":["Captopril Geolab"],"renal_adjustment":"Ajustar dose em insuficiência renal conforme função renal.","adverse_reactions":["Tosse seca, hipotensão, alteração do paladar, erupção/prurido e hipercalemia.","Angioedema, agranulocitose e deterioração renal são eventos importantes."],"contraindications":["Hipersensibilidade ao captopril, a outros inibidores da ECA ou a qualquer componente da formulação.","História de angioedema relacionado a tratamento prévio com inibidor da ECA.","Angioedema hereditário ou idiopático.","Gravidez.","Uso concomitante com alisquireno em pacientes com diabetes mellitus ou comprometimento renal relevante.","Uso concomitante com sacubitril/valsartana sem respeitar o intervalo de segurança previsto em bula."],"drug_interactions":["Diuréticos e depleção de sal/volume: hipotensão na primeira dose.","Espironolactona, suplementos ou sal de potássio: hipercalemia.","AINEs podem atenuar ação anti-hipertensiva; lítio pode atingir níveis tóxicos."],"safety_source_url":"https://geolab.com.br/wp-content/uploads/2021/05/CAPTOPRIL-Bula-Profissional.pdf","hepatic_adjustment":"Não há ajuste hepático específico geralmente necessário.","safety_reviewed_at":"2026-09-29","overdose_management":"Superdose causa principalmente hipotensão. Expansão volêmica e suporte hemodinâmico; hemodiálise pode remover captopril.","legacy_seed_original":{"status":"posology_verified","diseases":["Hipertensão Arterial Sistêmica","Urgência Hipertensiva","Insuficiência Cardíaca","Pós-IAM","Nefropatia Diabética"],"products":[{"name":"Capoten / Genérico","type":"Farmácia / Hospitalar","presentation":"Comprimidos 12,5 mg, 25 mg e 50 mg"}],"indication":"Hipertensão arterial sistêmica, insuficiência cardíaca crônica com fração de ejeção reduzida, pós-infarto do miocárdio e urgência hipertensiva / pseudocrise hipertensiva.","reviewed_at":"2026-10-30","formulations":[{"label":"Comprimidos 25 mg (Uso Oral ou Sublingual em Urgência)","route":"Oral (VO) ou Sublingual (SL)","cautions":"CONTRAINDICADO formalmente na gestação (teratogênico — oligohidrâmnio, anúria e malformações renais fetais) e em estenose bilateral de artérias renais.","dose_text":"Urgência Hipertensiva / Ambulatório: 25 mg a 50 mg via oral (ou sublingual para ação mais rápida em 15–30 min). Dose ambulatorial: 25 a 50 mg de 8 em 8 horas ou 12/12h.","population":"Adultos","source_url":"https://consultas.anvisa.gov.br/#/bulario/","duration_text":"Uso contínuo na HAS; dose pontual na urgência","interval_text":"A cada 8 a 12 horas","administration":"Ingerir 1 hora antes das refeições (alimentos reduzem a absorção em 30 a 40%).","max_daily_text":"150 mg/dia.","prescription_type":"Receita simples"}],"pregnancy_text":"ABSOLUTAMENTE CONTRAINDICADO na gestação.","renal_adjustment":"ClCr 10–50 mL/min: 75% da dose. ClCr < 10 mL/min: 50% da dose a cada 12 a 24 horas. Suspender se K+ > 5,5 mEq/L ou elevação de creatinina > 30-50%.","adverse_reactions":["Tosse seca persistente (por acúmulo de bradicinina — ocorre em até 15-20% dos pacientes)","Hipotensão postural na primeira dose","Hipercalemia","Angioedema de face, lábios e glote"],"contraindications":["Gestação em qualquer trimestre (Categoria X/D)","História prévia de angioedema associado a IECA","Estenose bilateral de artéria renal ou estenose em rim único","Uso concomitante com Sacubitril/Valsartana (aguardar janela de 36h)"],"drug_interactions":["AINEs reduzem o efeito anti-hipertensivo e aumentam nefrotoxicidade","Suplementos de potássio e Espironolactona aumentam risco de hipercalemia grave"],"therapeutic_class":"Anti-hipertensivos e Cardiovasculares · IECA de Curta Ação","hepatic_adjustment":"Não requer ajuste na insuficiência hepática.","pregnancy_category":"Categoria D/X (Teratogênico grave)"},"safety_review_status":"source_reviewed","indications_backfilled_at":"2026-10-02","legacy_seed_imported_from":"assets/js/bulario-seeds.js","source_urls_backfilled_at":"2026-10-02","clinical_status":"verified_strict_hours"}'::jsonb
