29","overdose_management":"Superdose é potencialmente fatal, com falência multiorgânica. Não há antídoto específico; suporte intensivo e toxicologia.","safety_review_status":"source_reviewed","indications_backfilled_at":"2026-10-02","source_urls_backfilled_at":"2026-10-02","clinical_status":"verified_strict_hours"}'::jsonb
