SET data = '{"scope":"expanded","status":"source_reviewed","products":[{"name":"Topamax","type":"marca comercial"}],"review_note":"Posologia de epilepsia, prevenção de migrânea e ajuste renal revisados contra bula oficial.","source_urls":["https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5424d59e-74f1-4c3c-b737-79e9776e0b60"],"formulations":[{"label":"Comprimidos 25/50/100 mg; cápsulas sprinkle em alguns produtos.","route":"VO","cautions":"Risco de parestesias, perda de peso, acidose metabólica, nefrolitíase, glaucoma agudo e déficit cognitivo; atenção especial à gestação.","dose_text":"Monoterapia da epilepsia em adultos e ≥10 anos: alvo 400 mg/dia divididos em 2 doses, com titulação. Prevenção de migrânea em ≥12 anos: alvo 100 mg/dia em 2 doses, titulando de 25 mg à noite na 1ª semana até 50 mg 12/12 h na 4ª semana.","population":"Adultos e pediatria conforme indicação","safe_limit":"400 mg/dia em muitos esquemas de epilepsia; titular gradualmente e ajustar pela função renal e tolerabilidade.","duration_text":"Tratamento contínuo enquanto houver benefício; retirar gradualmente.","interval_text":"Geralmente duas vezes ao dia após titulação. (administrado em intervalos regulares de 8/8h ou 12/12h conforme prescrição)","administration":"Via oral; manter boa hidratação. Cápsulas sprinkle podem ter técnica própria.","max_daily_text":"Epilepsia em monoterapia: 400 mg/dia no esquema de bula; migrânea: alvo 100 mg/dia.","posology_lines":["Epilepsia: iniciar baixo e titular; adulto frequentemente 100–400 mg/dia em 2 tomadas.","Profilaxia de enxaqueca: iniciar 25 mg à noite e titular até ~100 mg/dia."],"prescription_type":"Controle especial; conferir receituário vigente."}],"presentation":"Comprimidos 25/50/100 mg; cápsulas sprinkle em alguns produtos.","quality_audit":{"batch":"bul-06-251-300","scope":"presentation_source_safety_fields_and_targeted_medical_review","priority":"P1","screened_at":"2026-10-15","clinical_area":"Neurologia","review_status":"PENDING_CLINI