ia/Psiquiatria","review_status":"PENDING_CLINICAL_SOURCE_REVIEW","action_required":"Clobazam em apresentação genérica sem fonte ou segurança: checar epilepsia, dose por idade/peso, interações CYP e risco de sedação, tolerância e retirada.","formulation_count":1,"scientifically_validated":false,"generic_placeholder_forms":1,"prescription_copy_blocked":true,"missing_core_safety_fields":["renal_adjustment","hepatic_adjustment","contraindications","drug_interactions","adverse_reactions"],"missing_source_formulations":1,"repeated_formulation_label_groups":0,"retailer_or_aggregator_hosted_formulations":0},"source_batch_tag":"source_review_batch_01","batch_reviewed_at":"2026-10-02","source_review_note":"Clobazam: dose por peso em Lennox-Gastaut conferida em label oficial.","source_reviewed_at":"2026-10-02","posology_cleanup_at":"2026-10-02","clinical_reviewed_at":"2026-10-02","posology_cleanup_batch":"posology_cleanup_01","source_batch_checked_at":"2026-10-02","reviewed_at":"2026-11-02","clinical_status":"verified_strict_hours"}'::jsonb
