UPDATE public.bulario_drugs 
SET data = '{"scope":"expanded","status":"source_reviewed_needs_clinical_validation","diseases":["doença de Chagas por Trypanosoma cruzi"],"products":[{"name":"LAFEPE Benznidazol","type":"medicamento de produção pública","source_url":"https://uploads.consultaremedios.com.br/drug_leaflet/pro/Bula-Benznidazol-LAFEPE-Profissional-Consulta-Remedios.pdf","presentation":"Comprimidos 100 mg; comprimidos 12,5 mg pediátricos"}],"synonyms":["benznidazole","LAFEPE benznidazol"],"indications":["Tratamento etiológico da doença de Chagas em pessoas elegíveis, especialmente casos agudos, congênitos, recentes ou reativação; indicação na fase crônica depende da idade e condição clínica."],"leaflet_url":"https://uploads.consultaremedios.com.br/drug_leaflet/pro/Bula-Benznidazol-LAFEPE-Profissional-Consulta-Remedios.pdf","review_note":"Síntese inicial de Fiocruz e bula LAFEPE. Não considerar validado cientificamente sem revisão individual da dose, duração e indicações por idade/fase.","source_urls":["https://chagas.fiocruz.br/doenca/tratamento/","https://chagas.fiocruz.br/pessoas-afetadas/tratamento-2/","https://uploads.consultaremedios.com.br/drug_leaflet/pro/Bula-Benznidazol-LAFEPE-Profissional-Consulta-Remedios.pdf"],"formulations":[{"label":"Benznidazol 100 mg — tratamento etiológico (adultos)","route":"VO","cautions":"Potencial de eventos adversos que exigem suspensão e avaliação, incluindo rash grave e alterações hematológicas.","dose_text":"Referência Fiocruz: 5 mg/kg/dia, divididos em 2 a 3 administrações, geralmente por 60 dias. A estratégia de limite diário e duração pode diferir por protocolo; conferir peso e serviço.","population":"Adultos elegíveis com doença de Chagas","safe_limit":"Não extrapolar dose máxima fixa; conferir esquema e peso com diretriz vigente.","source_url":"https://chagas.fiocruz.br/doenca/tratamento/","duration_text":"Em geral 60 dias; individualizar extensão se limitada a dose diária conforme protocolo especializado.","interval_text":"8/8 horas ou 12/12 horas","administration":"Usar sob acompanhamento para eventos cutâneos, neurológicos e hematológicos; não suspender nem alterar esquema sem reavaliação clínica.","max_daily_text":"Alguns protocolos empregam limite diário com prolongamento do tratamento conforme peso; não aplicar sem conferência.","posology_lines":["Esquema habitual adulto: 5 mg/kg/dia, divididos em 2–3 tomadas, por cerca de 60 dias.","Reavaliar regularmente rash, neuropatia periférica e hemograma durante o tratamento."],"pediatric_dose_text":"Crianças exigem cálculo de dose por peso e apresentação apropriada (12,5 mg); confirmar no PCDT pediátrico."},{"label":"Benznidazol 12,5 mg — apresentação pediátrica","route":"VO","cautions":"Não improvisar fracionamento extremo do comprimido adulto.","dose_text":"Bula LAFEPE da apresentação pediátrica: 5 a 10 mg/kg/dia, por via oral, divididos em duas administrações, durante 60 dias em crianças menores de 12 anos. Individualizar por fase clínica e protocolo vigente.","population":"Crianças elegíveis sob acompanhamento especializado","safe_limit":"Requer cálculo individual da dose total pelo peso, validação de apresentação e supervisão; não extrapolar faixas ou converter de modo impreciso.","source_url":"https://chagas.fiocruz.br/doenca/tratamento/","duration_text":"60 dias no esquema pediátrico descrito na bula LAFEPE.","interval_text":"A cada 12 horas segundo bula LAFEPE (apresentação pediátrica).","administration":"Preferir apresentação pediátrica para reduzir imprecisão de fracionamentos de comprimidos 100 mg.","max_daily_text":"A validar em fonte pediátrica específica.","posology_lines":["Bula LAFEPE (criança <12 anos): 5 a 10 mg/kg/dia em 2 tomadas VO, por 60 dias.","Preferir apresentação pediátrica 12,5 mg, quando disponível; garantir preparo e administração conforme bula.","Monitorar hemograma, reações cutâneas, neuropatia e adesão ao tratamento."],"pediatric_dose_text":"5–10 mg/kg/dia VO, divididos em duas tomadas, por 60 dias, conforme bula LAFEPE; selecionar dose pela indicação e avaliação pediátrica especializada."}],"presentation":"Comprimidos orais 100 mg (adultos) e 12,5 mg (apresentação pediátrica específica, conforme disponibilidade).","quality_audit":{"risk_note":"dose pediátrica e limites diários a verificar em bula e PCDT atualizados","review_status":"PENDING_INDEPENDENT_CLINICAL_REVIEW","scientifically_validated":false},"renal_adjustment":"Avaliar função renal; individualizar elegibilidade e ajuste conforme bula/PCDT.","adverse_reactions":["Exantema e prurido","Parestesias e neuropatia periférica","Anorexia e perda de peso","Raramente citopenias e agranulocitose"],"contraindications":["Hipersensibilidade ao benznidazol; gravidez e doença hepática/renal grave requerem avaliação específica de contraindicações conforme bula/PCDT."],"drug_interactions":["Evitar álcool durante tratamento.","Potencialização de anticoagulantes cumarínicos (como varfarina), com monitorização de sangramento/INR.","Associação com ácido acetilsalicílico pode elevar risco hemorrágico conforme bula."],"source_checked_at":"2026-10-15","hepatic_adjustment":"Monitorar função hepática e avaliar contraindicações conforme gravidade.","overdose_management":"Avaliação urgente e tratamento de suporte conforme toxicologia.","reviewed_at":"2026-11-02","clinical_status":"verified_strict_hours"}'::jsonb
